'use strict';
/** Photo-realistic DPF cutaway with alpha vignette and pixel-composited soot/heat.
 * Replaces only the illustration; Overview menus and positioning remain untouched.
 */
const zlib = require('zlib');
const G = require('./kit/gauges');
const W = 740, H = 342, BW = 680, BH = 227, BX = 30, BY = 79;
const PHOTO = zlib.inflateSync(Buffer.from('', 'base64'));
if (PHOTO.length !== BW * BH * 4) throw new Error('DPF RGBA image size mismatch');
const CORE_X = 224, CORE_Y = 51, CORE_W = 257, CORE_H = 104;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const isNum = G.isNum;
const smooth = x => x * x * (3 - 2 * x);
const mix = (a, b, t) => a + (b - a) * t;

// The photographed opening has an asymmetric bevel. Each row gives the
// interior limits in source pixels, measured inside the metal lip.
const OPENING = [
    [51, 249, 463], [54, 241, 469], [62, 234, 475], [74, 229, 478],
    [91, 225, 480], [114, 224, 480], [130, 225, 478], [142, 229, 475],
    [149, 233, 470], [153, 239, 458], [155, 244, 450],
];

function noise(x, y) {
    let v = Math.imul(x + 31, 374761393) ^ Math.imul(y + 97, 668265263);
    v = Math.imul(v ^ (v >>> 13), 1274126177);
    return ((v ^ (v >>> 16)) >>> 0) / 4294967296;
}

function grain(x, y, size) {
    const gx = Math.floor(x / size), gy = Math.floor(y / size);
    const fx = smooth(x / size - gx), fy = smooth(y / size - gy);
    return mix(mix(noise(gx, gy), noise(gx + 1, gy), fx),
        mix(noise(gx, gy + 1), noise(gx + 1, gy + 1), fx), fy);
}

function ceramicPixels() {
    const pixels = [];
    for (let row = 1; row < OPENING.length; row++) {
        const [top, leftTop, rightTop] = OPENING[row - 1];
        const [bottom, leftBottom, rightBottom] = OPENING[row];
        for (let y = top; y < bottom; y++) {
            const t = (y - top) / (bottom - top);
            const left = mix(leftTop, leftBottom, t), right = mix(rightTop, rightBottom, t);
            for (let x = Math.ceil(left); x < right; x++) {
                const edge = smooth(clamp(Math.min(x - left, right - x, y - CORE_Y, CORE_Y + CORE_H - y) / 3, 0, 1));
                const i = (y * BW + x) * 4;
                // Green retains the photographed cell walls while suppressing the red cast.
                const texture = Math.sqrt(PHOTO[i + 1] / 255);
                const deposit = 0.52 * grain(x + 17, y, 4) + 0.33 * grain(x, y + 11, 13) + 0.15 * noise(x, y);
                const hotSpot = Math.exp(-1.4 * (((x - 361) / 119) ** 2 + ((y - 105) / 47) ** 2));
                const offset = ((y - CORE_Y) * CORE_W + x - CORE_X) * 4;
                pixels.push({ i, offset, edge, texture, deposit, hotSpot });
            }
        }
    }
    // Rank the textured deposits so their density corresponds to the
    // fraction of the visible ceramic covered by soot.
    const ranked = pixels.filter(pixel => pixel.edge > 0).sort((a, b) => a.deposit - b.deposit);
    ranked.forEach((pixel, index) => { pixel.rank = (index + 0.5) / ranked.length; });
    return ranked;
}

// The native Store renderer accepts recorded layers. Encode each raster as
// horizontal runs and let the kit cache the resulting renderer textures.
function rasterLayer(key, width, height, pixels, scale) {
    return G.layer(key, width, height, cv => {
        // Snap source pixel boundaries before the renderer applies fractional
        // fullscreen scaling, so neighbouring runs meet without alpha seams.
        const snap = n => Math.round(n * scale) / scale;
        for (let y = 0; y < height; y++) {
            const row = y * width * 4;
            const y0 = snap(y), y1 = snap(y + 1);
            for (let x = 0; x < width;) {
                const i = row + x * 4;
                const r = pixels[i], g = pixels[i + 1], b = pixels[i + 2], a = pixels[i + 3];
                let end = x + 1;
                while (end < width) {
                    const next = row + end * 4;
                    if (pixels[next + 3] !== a || (a && (pixels[next] !== r ||
                        pixels[next + 1] !== g || pixels[next + 2] !== b))) break;
                    end++;
                }
                if (a) cv.fillRect(snap(x), y0, snap(end) - snap(x), y1 - y0, [r, g, b, a]);
                x = end;
            }
        }
    }, scale);
}

let pixels, housing;
let previousSoot = -1, previousHeat = -1, previousScale, core;
function prepareArtwork() {
    pixels = ceramicPixels();
    housing = Buffer.from(PHOTO);
    // Neutralise the orange light baked into the ceramic, including the
    // antialiased perimeter underneath the dynamic layer.
    for (const { i, texture } of pixels) {
        const luma = 9 + 211 * texture;
        housing[i] = Math.round(luma);
        housing[i + 1] = Math.round(luma * 0.91);
        housing[i + 2] = Math.round(luma * 0.77);
    }
}

function ceramicLayer(soot, heat, scale) {
    const sootStep = Math.round(soot * 24), heatStep = Math.round(heat * 24);
    if (sootStep === previousSoot && heatStep === previousHeat && scale === previousScale) return core;
    const load = sootStep / 24, thermal = heatStep / 24;
    const coveredArea = 0.80 * clamp(load / 0.90, 0, 1);
    const brightness = Math.pow(thermal, 1.3);
    const frame = Buffer.alloc(CORE_W * CORE_H * 4);
    for (const { offset, edge, texture, deposit, hotSpot, rank } of pixels) {
        const coverage = smooth(clamp((coveredArea - rank) / 0.06 + 0.5, 0, 1));
        const attenuation = 1 - coverage * (0.85 + 0.10 * deposit);
        const cold = (9 + 211 * texture) * attenuation;
        const glow = brightness * (0.30 + 0.70 * hotSpot) *
            (0.04 + 0.96 * texture) * (1 - 0.32 * coverage);
        frame[offset] = Math.round(cold + (255 - cold) * glow);
        frame[offset + 1] = Math.round(cold * (0.91 - 0.52 * thermal) + 126 * glow);
        frame[offset + 2] = Math.round(cold * (0.77 - 0.68 * thermal) + 20 * glow);
        frame[offset + 3] = Math.round(255 * edge);
    }
    core = rasterLayer('dpf-core-' + sootStep + '-' + heatStep, CORE_W, CORE_H, frame, scale);
    previousSoot = sootStep;
    previousHeat = heatStep;
    previousScale = scale;
    return core;
}

function caption(cv, P, x, y, label, value, unit, decimals) {
    const n = isNum(value) ? value.toFixed(decimals) : '--', u = ' ' + unit;
    const valueWidth = cv.textWidth(n, 34, { font: 'light' });
    const left = x - (valueWidth + cv.textWidth(u, 18)) / 2;
    cv.text(label, x, y, 19, P.dim, { align: 'center' });
    cv.text(n, left, y + 30, 34, isNum(value) ? P.text : P.dim, { font: 'light' });
    cv.text(u, left + valueWidth, y + 30, 18, P.dim);
}

function drawDpf(cv, P, x0, y0, s) {
    const soot = isNum(s.soot) && s.sootMax > 0 ? clamp(s.soot / s.sootMax, 0, 1) : 0;
    const heat = isNum(s.tDpf) ? clamp((s.tDpf - 300) / 300, 0, 1) : 0;
    const bx = x0 + BX, by = y0 + BY;
    const scale = cv.textScale || 1;
    if (!housing) prepareArtwork();
    cv.blit(rasterLayer('dpf-housing', BW, BH, housing, scale), bx, by);
    cv.blit(ceramicLayer(soot, heat, scale), bx + CORE_X, by + CORE_Y);

    const leader = (points, end) => {
        cv.polyline(points.map(([x, y]) => [x0 + x, y0 + y]), 1.2, '#617b93');
        cv.circle(x0 + end[0], y0 + end[1], 2, '#8eaac0');
    };
    leader([[130, 86], [130, 115], [167, 142]], [167, 142]);
    leader([[370, 86], [370, 134]], [370, 134]);
    leader([[610, 86], [610, 107], [513, 137]], [513, 137]);
    leader([[370, 294], [274, 294], [261, 262]], [261, 262]);
    leader([[370, 294], [467, 294], [480, 262]], [480, 262]);

    caption(cv, P, x0 + 130, y0 + 22, 'Before DPF', s.T(s.tDpf), s.tUnit, 0);
    caption(cv, P, x0 + 370, y0 + 22, 'Soot', s.soot, 'g', 1);
    caption(cv, P, x0 + 610, y0 + 22, 'Ash', s.ash, 'g', 1);
    const dp = isNum(s.dp) ? s.dp.toFixed(0) : '--';
    cv.text('Pressure difference', x0 + 358, y0 + 321, 19, P.dim, { align: 'right' });
    const width = cv.text(dp, x0 + 375, y0 + 323, 30, isNum(s.dp) ? P.text : P.dim, { font: 'light' });
    cv.text(' mbar', x0 + 375 + width, y0 + 323, 18, P.dim);
}
module.exports = { drawDpf, W, H };
